<label class="form-wide"><span><i class="bi bi-geo-alt" aria-hidden="true"></i> Site<?= $kind==='transfers'?' de départ':'' ?> *</span><select name="site_id" data-livestock-site required><option value="">Sélectionner un site</option><?php foreach(Auth::sites() as $site): if(!in_array($site['code'],['FARM-MUT','FARM-DIK'],true)||!Auth::can('livestock',$sitePermission,(int)$site['id']))continue; ?><option value="<?=e($site['id'])?>" <?=Auth::currentSiteId()===(int)$site['id']?'selected':''?>><?=e($site['name'])?></option><?php endforeach; ?></select><small>Le choix s’applique uniquement à cette opération.</small></label>